import { isObservable, observable } from '@trpc/server/observable';
import type {
  AnyRouter,
  CreateContextCallback,
  ErrorHandlerOptions,
  inferClientTypes,
  inferRouterContext,
  MaybePromise,
} from '@trpc/server/unstable-core-do-not-import';
import {
  callProcedure,
  getErrorShape,
  getTRPCErrorFromUnknown,
  isAsyncIterable,
  isTrackedEnvelope,
  run,
  TRPCError,
} from '@trpc/server/unstable-core-do-not-import';

/**
 * Create a link that runs the router in the same process as the client
 */
export function localLink<TRouter extends AnyRouter>(
  opts: LocalLinkOptions<TRouter>,
): TRPCLink<TRouter> {
  const transformer = getTransformer(opts.transformer);
  return () => {
    return ({ op }) => {
      return observable((observer) => {
        const { type, path, input } = op;
        const ac = new AbortController();
        const signal = raceAbortSignals(op.signal, ac.signal);

        let ctx: inferRouterContext<TRouter> | undefined = undefined;

        const handleData = (data: unknown) => {
          let id: string | undefined = undefined;
          if (isTrackedEnvelope(data)) {
            id = data[0];
            data = data[1];
          }
          const transformed = transformer.output.deserialize(
            opts.router._def._config.transformer.output.serialize(data),
          );
          observer.next({
            result: {
              type: 'data',
              data: transformed,
              id,
            },
          });
        };

        const handleError = (cause: unknown) => {
          const error = getTRPCErrorFromUnknown(cause);
          opts.onError?.({
            error,
            type,
            path,
            input,
            ctx,
          });
          const errorShape = getErrorShape({
            config: opts.router._def._config,
            error,
            type,
            path,
            input,
            ctx,
          });
          const transformedError = transformer.output.deserialize(
            opts.router._def._config.transformer.output.serialize(errorShape),
          );
          observer.error(
            TRPCClientError.from({
              error: transformedError,
            }),
          );
        };

        run(async () => {
          ctx =
            (await opts.createContext?.()) ??
            ({} as inferRouterContext<TRouter>);
          const rawInput = transformer.input.serialize(input);

          const result = await callProcedure({
            router: opts.router,
            path,
            getRawInput: async () => rawInput,
            ctx,
            type,
            signal,
          });

          if (type !== 'subscription') {
            handleData(result);
            observer.complete();
            return;
          }

          observer.next({
            result: {
              type: 'started',
            },
          });

          if (isObservable(result)) {
            const sub = result.subscribe({
              next(data) {
                handleData(data);
              },
              error(err) {
                handleError(err);
              },
              complete() {
                observer.complete();
              },
            });
            ac.signal.addEventListener('abort', () => {
              sub.unsubscribe();
            });
          } else if (isAsyncIterable(result)) {
            run(async () => {
              for await (const data of result) {
                handleData(data);
              }
              observer.complete();
            }).catch(handleError);
          } else {
            throw new TRPCError({
              code: 'INTERNAL_SERVER_ERROR',
              message: `Subscription procedure on path "${path}" did not return an Observable or AsyncIterable`,
            });
          }
        }).catch(handleError);

        return () => {
          ac.abort();
        };
      });
    };
  };
}

