test('localLink supports Observable subscriptions', async () => {
  const ee = new EventEmitter();
  const t = initTRPC.create();

  const router = t.router({
    onMessage: t.procedure.subscription(() => {
      return observable<{ data: string }>((observer) => {
        const onMessage = (msg: string) => {
          observer.next({ data: msg });
        };
        ee.on('message', onMessage);
        return () => {
          ee.off('message', onMessage);
        };
      });
    }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  const received: string[] = [];
  const sub = client.onMessage.subscribe(undefined, {
    onData(data) {
      received.push(data.data);
    },
  });

  await vi.waitFor(() => {
    expect(ee.listenerCount('message')).toBe(1);
  });

  ee.emit('message', 'first');
  sub.unsubscribe();

  await vi.waitFor(() => {
    expect(ee.listenerCount('message')).toBe(0);
  });
  expect(received).toEqual(['first']);
});

test('localLink supports tracked envelopes', async () => {
  const ee = new EventEmitter();
  const t = initTRPC.create();
  const { tracked } = await import('@trpc/server/unstable-core-do-not-import');

  const router = t.router({
    onMessage: t.procedure.subscription(async function* () {
      let count = 0;
      for await (const [msg] of on(ee, 'message')) {
        yield tracked(String(++count), msg);
      }
    }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  const received: any[] = [];
  client.onMessage.subscribe(undefined, {
    onData(data) {
      received.push(data);
    },
  });

  await vi.waitFor(() => {
    expect(ee.listenerCount('message')).toBe(1);
  });

  ee.emit('message', 'first');
  ee.emit('message', 'second');

  await vi.waitFor(() => {
    expect(received).toEqual([
      {
        data: 'first',
        id: '1',
      },
      {
        data: 'second',
        id: '2',
      },
    ]);
  });
});

